import React, { useState, useEffect } from 'react';
import { generateParlays } from './services/geminiService';
import { League, RiskLevel, UserInputState, ParlayRecommendation } from './types';
import { InputForm } from './components/InputForm';
import { ParlayCard } from './components/ParlayCard';
import { PlayerProfileCard } from './components/PlayerProfileCard';
import { LoadingScreen } from './components/LoadingScreen';
import { LandingPage } from './components/LandingPage';
import { BarChart3, ShieldAlert, Home } from './components/Icons';

function App() {
  const [showLanding, setShowLanding] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [recommendations, setRecommendations] = useState<ParlayRecommendation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<UserInputState>({
    league: League.NBA,
    riskLevel: RiskLevel.MEDIUM,
    bankroll: 1000,
    filters: ''
  });
  const [isAutoRefresh, setIsAutoRefresh] = useState(false);

  // Auto-refresh logic
  useEffect(() => {
    let intervalId: ReturnType<typeof setInterval> | undefined;

    if (isAutoRefresh) {
      intervalId = setInterval(() => {
        if (!isLoading) {
          console.log("System: Executing scheduled background data sync...");
          handleGenerate(true);
        }
      }, 30000); // 30 seconds refresh cycle
    }

    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [isAutoRefresh, isLoading, formData]);

  const handleGenerate = async (isBackground = false) => {
    setIsLoading(true);
    setError(null);

    // Only clear previous results if it's a manual action, not a background update
    if (!isBackground) {
        setRecommendations([]);
    }

    try {
      const results = await generateParlays(formData.league, formData.riskLevel, formData.filters);
      setRecommendations(results);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsLoading(false);
    }
  };

  if (showLanding) {
    return (
        <LandingPage 
            onEnter={() => setShowLanding(false)} 
            hasActiveSession={recommendations.length > 0 || formData.filters !== ''}
        />
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans selection:bg-emerald-500/30">
      {/* Header */}
      <header className="border-b border-gray-800 bg-gray-900/50 backdrop-blur sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => setShowLanding(true)}>
            <div className="bg-emerald-500/10 p-2 rounded border border-emerald-500/20">
              <BarChart3 className="text-emerald-500" size={24} />
            </div>
            <div>
              <h1 className="text-lg font-bold text-white tracking-tight">PRR <span className="text-gray-500 text-sm font-normal">| Parlay Recommendation Robot</span></h1>
              <div className="text-[10px] font-mono text-emerald-400 uppercase tracking-widest">v1.0.4 MVP • LIVE CONNECTED</div>
            </div>
          </div>

          {/* Mobile Home Button */}
          <button 
             onClick={() => setShowLanding(true)}
             className="md:hidden p-2 text-gray-400 hover:text-white"
             title="Return Home"
          >
             <Home size={20} />
          </button>

          {/* Desktop Nav */}
          <div className="hidden md:flex items-center gap-6 text-sm text-gray-400">

             {/* Home Button (Desktop) */}
             <button 
                onClick={() => setShowLanding(true)}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg hover:bg-gray-800 hover:text-white transition-all group"
             >
                <Home size={16} className="text-gray-500 group-hover:text-emerald-400 transition-colors" />
                <span className="font-mono text-xs font-medium uppercase tracking-wider">Exit Terminal</span>
             </button>

             <div className="h-4 w-px bg-gray-800"></div>

             <span className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${isAutoRefresh ? 'bg-emerald-500 animate-pulse' : 'bg-gray-500'}`}></div> 
                {isAutoRefresh ? 'Live Data Stream Active' : 'System Online'}
             </span>
             <span className="font-mono">LATENCY: 42ms</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Intro / Dashboard */}
        <div className="mb-8">
          <InputForm 
            formData={formData} 
            setFormData={setFormData} 
            onSubmit={() => handleGenerate(false)} 
            isLoading={isLoading}
            isAutoRefresh={isAutoRefresh}
            setIsAutoRefresh={setIsAutoRefresh}
          />
        </div>

        {/* Results Area */}
        <div className="space-y-6">
          {error && (
            <div className="bg-rose-950/30 border border-rose-900 text-rose-200 p-4 rounded-lg flex items-center gap-3">
              <ShieldAlert size={20} />
              <div>
                <p className="font-bold">System Error</p>
                <p className="text-sm opacity-80">{error}</p>
              </div>
            </div>
          )}

          {recommendations.length > 0 && (
             <div className="flex items-center justify-between mb-4">
               <h3 className="text-xl font-bold text-white">
                 {recommendations[0].type === 'player_profile' ? 'Player Intelligence Report' : 'Optimized Candidates'}
               </h3>
               <div className="flex items-center gap-4">
                 {isLoading && isAutoRefresh && <span className="text-xs text-emerald-400 animate-pulse font-mono">SYNCING LIVE ODDS...</span>}
                 <span className="text-sm text-gray-500 font-mono">Sorted by Utility Score (EV - Risk)</span>
               </div>
             </div>
          )}

          <div className="grid gap-6">
            {recommendations.map((item, index) => {
               if (item.type === 'player_profile') {
                   return <PlayerProfileCard key={item.id || index} data={item} />;
               }
               return <ParlayCard key={item.id || index} parlay={item} index={index} />;
            })}
          </div>

          {!isLoading && recommendations.length === 0 && !error && (
            <div className="text-center py-20 border border-dashed border-gray-800 rounded-xl">
              <div className="inline-block p-4 rounded-full bg-gray-900 mb-4">
                <BarChart3 className="text-gray-600" size={32} />
              </div>
              <h3 className="text-gray-400 font-medium text-lg">Awaiting Input Parameters</h3>
              <p className="text-gray-600 max-w-md mx-auto mt-2">
                Configure the model above and initialize the simulation to receive mathematically optimized recommendations.
              </p>
            </div>
          )}
        </div>
      </main>

      {/* Disclaimer Footer */}
      <footer className="border-t border-gray-900 mt-12 py-8 bg-gray-950">
        <div className="max-w-7xl mx-auto px-4 text-center">
            <p className="text-xs text-gray-600 max-w-2xl mx-auto leading-relaxed">
              DISCLAIMER: This system is for informational and entertainment purposes only. The "Parlay Recommendation Robot" uses simulated historical data and probability models which do not guarantee future results. Gambling involves risk. Please gamble responsibly. If you or someone you know has a gambling problem, call 1-800-GAMBLER.
            </p>
            <p className="text-[10px] text-gray-700 mt-4 font-mono">
              ENGINE: XGBoost v1.7.6 | DATA: SportRadar/Genius (Simulated) | LATENCY: 42ms
            </p>
        </div>
      </footer>

      {/* Only show full screen loader if we have no data to show yet. Background refreshes are silent/subtle. */}
      {isLoading && recommendations.length === 0 && <LoadingScreen />}
    </div>
  );
}

export default App;

