import React, { useState, useEffect, useRef } from 'react';
import { League, RiskLevel, UserInputState } from '../types';
import { BrainCircuit, DollarSign, RefreshCw, Zap, Database, Activity, Globe, Search, Clock, X } from './Icons';

interface InputFormProps {
  formData: UserInputState;
  setFormData: React.Dispatch<React.SetStateAction<UserInputState>>;
  onSubmit: () => void;
  isLoading: boolean;
}

export const InputForm: React.FC<InputFormProps> = ({ 
  formData, 
  setFormData, 
  onSubmit, 
  isLoading
}) => {
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('prr_search_history');
    if (saved) {
      try {
        setRecentSearches(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse search history", e);
      }
    }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'bankroll' ? parseFloat(value) : value
    }));
    if (name === 'filters') {
      setShowSuggestions(true);
    }
  };

  const saveToHistory = (term: string) => {
    if (!term || term.trim().length < 2) return;
    const cleanTerm = term.trim();
    // Remove duplicates and keep only last 5
    const newHistory = [cleanTerm, ...recentSearches.filter(s => s.toLowerCase() !== cleanTerm.toLowerCase())].slice(0, 5);
    setRecentSearches(newHistory);
    localStorage.setItem('prr_search_history', JSON.stringify(newHistory));
  };

  const clearHistory = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent closing dropdown immediately
    setRecentSearches([]);
    localStorage.removeItem('prr_search_history');
    setShowSuggestions(false);
  };

  const handleSubmission = () => {
    saveToHistory(formData.filters);
    setShowSuggestions(false);
    onSubmit();
  };

  const handleSuggestionClick = (term: string) => {
    setFormData(prev => ({ ...prev, filters: term }));
    setShowSuggestions(false);
  };

  // Filter suggestions based on input
  const filteredSuggestions = recentSearches.filter(s => 
    s.toLowerCase().includes(formData.filters.toLowerCase())
  );

  const shouldShowDropdown = showSuggestions && (filteredSuggestions.length > 0 || (formData.filters === '' && recentSearches.length > 0));

  return (
    <div className="bg-gray-850 p-6 rounded-xl border border-gray-800 shadow-lg relative z-30">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div className="flex items-center gap-2">
          <BrainCircuit className="text-emerald-400" size={24} />
          <h2 className="text-xl font-bold text-white">Model Configuration</h2>
        </div>

        <div className="flex items-center gap-3">
          {/* Refresh Data Button */}
          <button 
            onClick={handleSubmission}
            disabled={isLoading}
            className="flex items-center justify-center p-2 bg-gray-900 border border-gray-800 rounded-lg hover:bg-gray-800 hover:border-gray-700 transition-all text-gray-400 hover:text-white disabled:opacity-50 disabled:cursor-not-allowed group"
            title="Force Refresh Data"
          >
            <RefreshCw size={18} className={`group-hover:text-emerald-400 transition-colors ${isLoading ? 'animate-spin text-emerald-500' : ''}`} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

        {/* Search Bar - Takes up more space now */}
        <div className="md:col-span-6 relative" ref={searchContainerRef}>
          <label className="block text-xs text-emerald-400 uppercase tracking-wider mb-2 font-bold flex items-center gap-2">
             <Search size={12} /> Search Player / Team
          </label>
          <div className="relative group">
            <input 
              type="text" 
              name="filters"
              value={formData.filters}
              onChange={handleChange}
              onFocus={() => setShowSuggestions(true)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSubmission();
              }}
              autoComplete="off"
              placeholder="e.g. 'LeBron James' or 'Lakers'"
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 pl-10 focus:outline-none focus:border-emerald-500 transition-colors group-hover:border-gray-600"
            />
            <Search size={16} className="absolute left-3 top-3.5 text-gray-500 group-hover:text-emerald-400 transition-colors" />
            <div className="absolute right-3 top-3.5">
                <span className="text-[10px] bg-gray-800 text-gray-400 px-1.5 py-0.5 rounded border border-gray-700">LIVE LOOKUP</span>
            </div>
          </div>

          {/* Search History Dropdown */}
          {shouldShowDropdown && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-700 rounded-lg shadow-xl overflow-hidden z-50">
              <div className="py-1">
                <div className="px-3 py-2 text-[10px] uppercase text-gray-500 font-bold tracking-wider border-b border-gray-800 flex justify-between items-center">
                  <span>Recent Searches</span>
                  <button onClick={clearHistory} className="text-gray-600 hover:text-rose-400 transition-colors flex items-center gap-1">
                    <X size={10} /> Clear
                  </button>
                </div>
                {filteredSuggestions.map((term, idx) => (
                  <div 
                    key={idx}
                    onClick={() => handleSuggestionClick(term)}
                    className="px-3 py-2.5 hover:bg-gray-800 cursor-pointer flex items-center gap-3 transition-colors text-sm text-gray-300"
                  >
