function App() {
  const [showLanding, setShowLanding] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [recommendations, setRecommendations] = useState<ParlayRecommendation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<UserInputState>({
    league: League.NBA,
    riskLevel: RiskLevel.MEDIUM,
    bankroll: 1000,
    filters: ''
  });

  // Auto-trigger generation when entering the terminal
  useEffect(() => {
    if (!showLanding && recommendations.length === 0 && !isLoading) {
      console.log("System: Initializing Daily Top 3...");
      handleGenerate(false);
    }
  }, [showLanding]);

  // Auto-refresh logic (Always Active)
  useEffect(() => {
    const intervalId = setInterval(() => {
      if (!isLoading && !showLanding) {
        console.log("System: Executing scheduled background data sync...");
        handleGenerate(true);
      }
    }, 30000); // 30 seconds refresh cycle

    return () => clearInterval(intervalId);
  }, [isLoading, formData, showLanding]);

  const handleGenerate = async (isBackground = false, overrideParams?: UserInputState) => {
    setIsLoading(true);
    setError(null);

    // Use override params if provided, otherwise current state
    const params = overrideParams || formData;

    // Only clear previous results if it's a manual action, not a background update
    if (!isBackground) {
        setRecommendations([]);
    }

    try {
      const results = await generateParlays(params.league, params.riskLevel, params.filters);
      setRecommendations(results);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePlayerClick = (playerName: string) => {
    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });

    // Update state to reflect the new search
    const newParams = { ...formData, filters: playerName };
    setFormData(newParams);

    // Trigger generation with new params immediately
    handleGenerate(false, newParams);
  };

  if (showLanding) {
    return (
        <LandingPage 
            onEnter={() => setShowLanding(false)} 
            hasActiveSession={recommendations.length > 0 || formData.filters !== ''}
        />
    );
