        }))
    }));
};

export const generateParlays = async (
  league: League,
  risk: RiskLevel,
  filters: string
): Promise<ParlayRecommendation[]> => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in environment variables.");
    }

    const ai = new GoogleGenAI({ apiKey });
    const modelId = "gemini-2.5-flash"; // Flash is faster and cheaper

    const isPlayerSearch = filters && filters.length > 2;
    const isDailyTop3 = !filters || filters.length === 0;

    const prompt = `
      Act as an Elite Algorithmic Betting Engine & Chief Mathematician.

      MODE: ${isPlayerSearch ? "SINGLE PLAYER DEEP DIVE PROFILE" : "DAILY TOP 3 (3-LEG PARLAYS)"}

      Context:
      - League: ${league}
      - User Focus: ${filters || "Daily System Picks (Best Value Today)"}
      - Strategy: ${risk === RiskLevel.HIGH ? "Correlated Aggressive (High Variance)" : "High-Floor Safety (Low Variance)"}

      ### EXECUTION CONSTRAINTS (CRITICAL):
      ${isDailyTop3 ? `
      1. **STRUCTURE**: You MUST return exactly THREE (3) distinct parlays.
      2. **LEGS**: Each parlay MUST have exactly THREE (3) legs.
      3. **TIMING**: All picks must be for games happening TODAY.
      ` : ''}

      ### MATHEMATICAL FRAMEWORK:
      1. **Bayesian Inference**: Update implied probability priors with recent form likelihoods.
      2. **Correlation**: Use Gaussian Copulas to boost probability for correlated legs (e.g., QB yards + WR yards).
      3. **Kelly Criterion**: Suggest stake sizing based on calculated edge.

      ### OUTPUT FORMAT RULES (STRICT):
      1. **RETURN RAW JSON ONLY**.
      2. **NO MARKDOWN**. Do not use \`\`\`json blocks.
      3. **NO CONVERSATIONAL TEXT**. Start immediately with '{'.
      4. **NO TABLES**.

      JSON Structure:
      {
        "recommendations": [
          {
            "type": "parlay" | "player_profile",
            "id": "string",
            "summary": "string (Explain the math)",
            "totalOdds": number,
            "jointProbAdjusted": number,
            "expectedValue": number,
            "kellyStake": number,
            "correlationScore": number,
            "varianceScore": number,
            "timestamp": "string",
            "legs": [
              {
                "playerName": "string",
                "team": "string",
                "opponent": "string",
                "statType": "string",
                "line": number,
                "prediction": "Over" | "Under",
                "bookOdds": number,
                "modelProb": number,
                "impliedProb": number,
                "edge": number,
                "rationale": "string"
              }
            ]
          }
        ]
      }
    `;

    try {
        console.log("Attempting generation with Live Search Grounding...");
        const response = await ai.models.generateContent({
            model: modelId,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            }
        });

        if (!response.text) throw new Error("No text returned from model");
        return parseResponse(response.text, isPlayerSearch);

    } catch (error: any) {
        console.warn("Primary generation failed. Checking for fallback conditions...", error);

        // Detect 429 Quota errors (specifically Search Grounding or General Quota)
        // Error message often contains "Quota exceeded for metric: ... search_grounding_request..."
        const isQuotaError = 
            error.status === 429 || 
            (error.message && (
                error.message.includes('429') || 
                error.message.includes('quota') || 
                error.message.includes('search_grounding') ||
                error.message.includes('RESOURCE_EXHAUSTED')
            ));

        if (isQuotaError) {
            console.log("Search quota exceeded. Falling back to internal knowledge simulation.");

            const fallbackPrompt = prompt + `
            \n\nSYSTEM NOTICE: LIVE SEARCH IS UNAVAILABLE DUE TO QUOTA LIMITS.
            1. You must now simulate the "Live Odds" and lines based on your internal knowledge of player averages, recent performance, and standard bookmaker pricing logic.
            2. Mark all rationale fields with prefix: "[Simulated Data] ".
            3. Proceed with generating the JSON as requested.
            `;

            // Retry without tools
            const fallbackResponse = await ai.models.generateContent({
                model: modelId,
                contents: fallbackPrompt,
                config: {
                    // No tools provided here to bypass search quota
                }
            });

            if (!fallbackResponse.text) throw new Error("No text returned from fallback generation");
            return parseResponse(fallbackResponse.text, isPlayerSearch);
        }

        // Re-throw if it's not a recoverable quota error
        throw error;
    }
};

