const calculateSmartEdge = (prob: number, odds: number) => {
    // implied prob of -110 is ~52.38%
    const decimalOdds = odds > 0 ? (odds / 100) + 1 : (100 / Math.abs(odds)) + 1;
    const implied = 1 / decimalOdds;
    const edge = (prob - implied) * 100;
    return { implied, edge };
};

