  return (
    <div className={`grid grid-cols-12 gap-4 p-4 border-b border-gray-800 transition-colors items-center ${isBest ? 'bg-emerald-950/20 hover:bg-emerald-950/30' : 'bg-gray-900 hover:bg-gray-800/50'}`}>
