export enum League {
  NFL = 'NFL',
  NBA = 'NBA',
  MLB = 'MLB'
}

export enum RiskLevel {
  VERY_LOW = 'Safe (High Probability)',
  LOW = 'Conservative (Positive EV)',
  MEDIUM = 'Balanced (Standard)',
  HIGH = 'Aggressive (High Return)',
  VERY_HIGH = 'Moonshot (Extreme Odds)'
}

export interface BetLeg {
  playerId: string;
  playerName: string;
  team: string;
  opponent: string;
  statType: string; // e.g., "Points", "Rebounds", "Passing Yards"
  line: number;
  prediction: 'Over' | 'Under';
  bookOdds: number; // American odds, e.g., -110
  modelProb: number; // 0.0 to 1.0
  impliedProb: number; // 0.0 to 1.0
  edge: number; // Percentage points
  rationale: string;
}

export interface ParlayRecommendation {
  type?: 'parlay' | 'player_profile'; // Discriminator for UI rendering
  id: string;
  legs: BetLeg[];
  totalOdds: number; // American odds, e.g., +260
  jointProbAdjusted: number; // Correlation adjusted probability
  expectedValue: number; // EV %
  kellyStake: number; // Recommended bankroll %
  correlationScore: number; // 0 to 1, how correlated the plays are
  varianceScore: number; // High variance = high risk
  summary: string;
  timestamp: string;
}

export interface UserInputState {
  league: League;
  riskLevel: RiskLevel;
  bankroll: number;
  filters: string;
  statType: string;
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { League, RiskLevel, UserInputState } from '../types';
import { BrainCircuit, DollarSign, RefreshCw, Zap, Database, Activity, Globe, Search, Clock, X, BarChart3, TrendingUp, ShieldAlert } from './Icons';

interface InputFormProps {
  formData: UserInputState;
  setFormData: React.Dispatch<React.SetStateAction<UserInputState>>;
  onSubmit: () => void;
  isLoading: boolean;
}

export const InputForm: React.FC<InputFormProps> = ({ 
  formData, 
  setFormData, 
  onSubmit, 
  isLoading
}) => {
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('prr_search_history');
    if (saved) {
      try {
        setRecentSearches(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse search history", e);
      }
    }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    // Reset stat type if league changes to avoid invalid combinations
    if (name === 'league') {
        setFormData(prev => ({
          ...prev,
          league: value as League,
          statType: 'Any'
        }));
    } else {
        setFormData(prev => ({
          ...prev,
          [name]: name === 'bankroll' ? parseFloat(value) : value
        }));
    }

    if (name === 'filters') {
      setShowSuggestions(true);
    }
  };

  const saveToHistory = (term: string) => {
    if (!term || term.trim().length < 2) return;
    const cleanTerm = term.trim();
    // Remove duplicates and keep only last 5
    const newHistory = [cleanTerm, ...recentSearches.filter(s => s.toLowerCase() !== cleanTerm.toLowerCase())].slice(0, 5);
    setRecentSearches(newHistory);
    localStorage.setItem('prr_search_history', JSON.stringify(newHistory));
  };

  const clearHistory = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent closing dropdown immediately
    setRecentSearches([]);
    localStorage.removeItem('prr_search_history');
    setShowSuggestions(false);
  };

  const handleSubmission = () => {
    saveToHistory(formData.filters);
    setShowSuggestions(false);
    onSubmit();
  };

  const handleSuggestionClick = (term: string) => {
    setFormData(prev => ({ ...prev, filters: term }));
    setShowSuggestions(false);
  };

  const handleRiskSelection = (risk: RiskLevel) => {
    setFormData(prev => ({ ...prev, riskLevel: risk }));
  };

  // Filter suggestions based on input
  const filteredSuggestions = recentSearches.filter(s => 
    s.toLowerCase().includes(formData.filters.toLowerCase())
  );

  const shouldShowDropdown = showSuggestions && (filteredSuggestions.length > 0 || (formData.filters === '' && recentSearches.length > 0));

  // Determine available stat options based on selected League
  const statOptions = useMemo(() => {
    switch(formData.league) {
        case League.NBA: return ['Any', 'Points', 'Rebounds', 'Assists', 'Threes', 'PRA', 'Steals/Blocks'];
        case League.NFL: return ['Any', 'Passing Yds', 'Rushing Yds', 'Receiving Yds', 'Touchdowns'];
        case League.MLB: return ['Any', 'Strikeouts', 'Total Bases', 'Hits', 'Home Runs'];
        default: return ['Any'];
    }
  }, [formData.league]);

  // Visual configuration for the Risk Gauge
  const riskConfig = [
    { level: RiskLevel.VERY_LOW, color: 'bg-emerald-500', label: 'Safe', icon: <ShieldAlert size={12} /> },
    { level: RiskLevel.LOW, color: 'bg-teal-500', label: 'Low', icon: <Activity size={12} /> },
    { level: RiskLevel.MEDIUM, color: 'bg-yellow-500', label: 'Med', icon: <TrendingUp size={12} /> },
    { level: RiskLevel.HIGH, color: 'bg-orange-500', label: 'High', icon: <Zap size={12} /> },
    { level: RiskLevel.VERY_HIGH, color: 'bg-rose-600', label: 'Max', icon: <BrainCircuit size={12} /> }
  ];

  return (
    <div className="bg-gray-850 p-6 rounded-xl border border-gray-800 shadow-lg relative z-30">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div className="flex items-center gap-2">
          <BrainCircuit className="text-emerald-400" size={24} />
          <h2 className="text-xl font-bold text-white">Model Configuration</h2>
        </div>

        <div className="flex items-center gap-3">
          {/* Refresh Data Button */}
          <button 
            onClick={handleSubmission}
            disabled={isLoading}
            className="flex items-center justify-center p-2 bg-gray-900 border border-gray-800 rounded-lg hover:bg-gray-800 hover:border-gray-700 transition-all text-gray-400 hover:text-white disabled:opacity-50 disabled:cursor-not-allowed group"
            title="Force Refresh Data"
          >
            <RefreshCw size={18} className={`group-hover:text-emerald-400 transition-colors ${isLoading ? 'animate-spin text-emerald-500' : ''}`} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

        {/* Search Bar */}
        <div className="md:col-span-4 relative" ref={searchContainerRef}>
          <label className="block text-xs text-emerald-400 uppercase tracking-wider mb-2 font-bold flex items-center gap-2">
             <Search size={12} /> Search Player / Team
          </label>
          <div className="relative group">
            <input 
              type="text" 
              name="filters"
              value={formData.filters}
              onChange={handleChange}
              onFocus={() => setShowSuggestions(true)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSubmission();
              }}
              autoComplete="off"
              placeholder="e.g. 'LeBron' or 'Lakers'"
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 pl-10 focus:outline-none focus:border-emerald-500 transition-colors group-hover:border-gray-600 text-sm"
            />
            <Search size={16} className="absolute left-3 top-3.5 text-gray-500 group-hover:text-emerald-400 transition-colors" />
            <div className="absolute right-3 top-3.5">
                <span className="text-[10px] bg-gray-800 text-gray-400 px-1.5 py-0.5 rounded border border-gray-700">LIVE LOOKUP</span>
            </div>
          </div>

          {/* Search History Dropdown */}
          {shouldShowDropdown && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-700 rounded-lg shadow-xl overflow-hidden z-50">
              <div className="py-1">
                <div className="px-3 py-2 text-[10px] uppercase text-gray-500 font-bold tracking-wider border-b border-gray-800 flex justify-between items-center">
                  <span>Recent Searches</span>
                  <button onClick={clearHistory} className="text-gray-600 hover:text-rose-400 transition-colors flex items-center gap-1">
                    <X size={10} /> Clear
                  </button>
                </div>
                {filteredSuggestions.map((term, idx) => (
                  <div 
                    key={idx}
                    onClick={() => handleSuggestionClick(term)}
                    className="px-3 py-2.5 hover:bg-gray-800 cursor-pointer flex items-center gap-3 transition-colors text-sm text-gray-300"
                  >
                    <Clock size={14} className="text-gray-500" />
                    {term}
                  </div>
                ))}
                {filteredSuggestions.length === 0 && (
                   <div className="px-3 py-4 text-center text-xs text-gray-600 italic">
                     No matching history
                   </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* League Selector */}
        <div className="md:col-span-2">
          <label className="block text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium">League</label>
          <div className="relative">
            <select 
              name="league"
              value={formData.league}
              onChange={handleChange}
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 appearance-none focus:outline-none focus:border-emerald-500 transition-colors text-sm"
            >
              {Object.values(League).map((l) => (
                <option key={l} value={l}>{l}</option>
              ))}
            </select>
            <div className="absolute right-3 top-3.5 pointer-events-none text-gray-500">
               <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
            </div>
          </div>
        </div>

        {/* Stat Focus Selector */}
        <div className="md:col-span-2">
          <label className="block text-xs text-emerald-400 uppercase tracking-wider mb-2 font-bold flex items-center gap-1">
             <BarChart3 size={12} /> Stat Focus
          </label>
          <div className="relative">
             <select 
              name="statType"
              value={formData.statType}
              onChange={handleChange}
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 appearance-none focus:outline-none focus:border-emerald-500 transition-colors text-sm"
            >
              {statOptions.map((opt) => (
                <option key={opt} value={opt}>{opt}</option>
              ))}
            </select>
            <div className="absolute right-3 top-3.5 pointer-events-none text-gray-500">
               <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
            </div>
          </div>
        </div>

        {/* Custom Visual Risk Gauge */}
        <div className="md:col-span-4">
          <label className="block text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium flex justify-between">
            <span>Risk Tolerance</span>
            <span className="text-white font-mono text-[10px]">{formData.riskLevel}</span>
          </label>
          <div className="flex items-center gap-1 bg-gray-900 p-1 rounded-lg border border-gray-700 h-[46px]">
            {riskConfig.map((config, index) => {
              const isSelected = formData.riskLevel === config.level;
              return (
                <button
                  key={config.level}
                  onClick={() => handleRiskSelection(config.level)}
                  className={`
                    flex-1 h-full rounded transition-all duration-300 flex items-center justify-center gap-1 group relative
                    ${isSelected ? `${config.color} text-gray-900 shadow-lg` : 'hover:bg-gray-800 text-gray-500 hover:text-gray-300'}
                  `}
                  title={config.level}
                >
                  <span className={`${isSelected ? 'scale-110' : 'scale-100'} transition-transform`}>
                    {config.icon}
                  </span>
                  {/* Tooltip on hover if not selected */}
                  {!isSelected && (
                     <div className="hidden group-hover:block absolute bottom-full mb-2 left-1/2 -translate-x-1/2 text-[10px] bg-gray-950 text-white px-2 py-1 rounded border border-gray-800 whitespace-nowrap z-20">
                        {config.level}
                     </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>

        {/* Bankroll (Moved below to balance layout if needed, or kept in flow. 
            Adjusting layout to 12 columns allows Risk to take 4 cols, Bankroll to take 2/remaining) */}
        {/* Note: I removed Bankroll from the grid above to replace it with the wide Risk Gauge. 
            I will re-insert Bankroll here in a new row or compact it. Let's compact it. */}
      </div>

      {/* Row 2: Bankroll & Action */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mt-6 items-end">
         <div>
            <label className="block text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium">Bankroll Allocation ($)</label>
            <div className="relative">
                <input 
                type="number" 
                name="bankroll"
                value={formData.bankroll}
                onChange={handleChange}
                className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 pl-10 focus:outline-none focus:border-emerald-500 transition-colors font-mono text-sm"
                />
                <DollarSign size={16} className="absolute left-3 top-3.5 text-gray-500" />
            </div>
         </div>

         <div className="flex justify-end">
            <button 
            onClick={handleSubmission} 
            disabled={isLoading}
            className={`
                w-full sm:w-auto flex items-center justify-center gap-2 px-8 py-3 rounded-lg font-bold tracking-wide transition-all
                ${isLoading 
                ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-500/20 hover:shadow-emerald-500/40 active:transform active:scale-95'
                }
            `}
            >
            {isLoading ? (
                <>
                <RefreshCw className="animate-spin" size={18} />
                SCANNING BOOKS...
                </>
            ) : (
                <>
                <BrainCircuit size={18} />
                RUN SIMULATION
                </>
            )}
            </button>
         </div>
      </div>

      {/* Live Data Sources Indicator */}
      <div className="mt-4 p-3 bg-gray-900/50 rounded-lg border border-gray-800 flex flex-wrap gap-4 items-center animate-fadeIn">
          <span className="text-[10px] uppercase text-gray-500 font-bold tracking-widest flex items-center gap-1">
              <Globe size={10} /> Live Grounding:
          </span>
          <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
              <span className="text-xs text-gray-300 font-medium">Live Web Search (Google Grounding)</span>
          </div>
          <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse delay-75"></div>
              <span className="text-xs text-gray-300 font-medium">DK / FD / PrizePicks / Underdog</span>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { generateParlays } from './services/geminiService';
import { League, RiskLevel, UserInputState, ParlayRecommendation } from './types';
import { InputForm } from './components/InputForm';
import { ParlayCard } from './components/ParlayCard';
import { PlayerProfileCard } from './components/PlayerProfileCard';
import { LoadingScreen } from './components/LoadingScreen';
import { LandingPage } from './components/LandingPage';
import { BarChart3, ShieldAlert, Home, Zap } from './components/Icons';

function App() {
  const [showLanding, setShowLanding] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [recommendations, setRecommendations] = useState<ParlayRecommendation[]>([]);
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<UserInputState>({
    league: League.NBA,
    riskLevel: RiskLevel.MEDIUM,
    bankroll: 1000,
    filters: '',
    statType: 'Any'
  });

  // Auto-trigger generation when entering the terminal
  useEffect(() => {
    if (!showLanding && recommendations.length === 0 && !isLoading) {
      console.log("System: Initializing Daily Top 3...");
      handleGenerate(false);
    }
  }, [showLanding]);

  // Auto-refresh logic (Always Active)
  // Increased to 60 seconds to avoid 429 Rate Limit errors
  useEffect(() => {
    const intervalId = setInterval(() => {
      if (!isLoading && !showLanding) {
        console.log("System: Executing scheduled background data sync...");
        handleGenerate(true);
      }
    }, 60000); // 60 seconds refresh cycle

    return () => clearInterval(intervalId);
  }, [isLoading, formData, showLanding]);

  const handleGenerate = async (isBackground = false, overrideParams?: UserInputState) => {
    setIsLoading(true);
    // Don't clear error on background refresh if it's already showing a rate limit, so user can see it
    if (!isBackground) setError(null);

    // Use override params if provided, otherwise current state
    const params = overrideParams || formData;

    // Only clear previous results if it's a manual action, not a background update
    if (!isBackground) {
        setRecommendations([]);
    }

    try {
      const results = await generateParlays(params.league, params.riskLevel, params.filters, params.statType);
      setRecommendations(results);
      setLastSyncTime(new Date());
      setError(null); // Clear error on success
    } catch (err) {
      let errorMessage = err instanceof Error ? err.message : "An unexpected error occurred.";

      // Attempt to clean up raw JSON errors if they leak through
      if (errorMessage.includes('{"error":')) {
         try {
             // Extract the message from the Google API error JSON structure
             const match = errorMessage.match(/"message":\s*"([^"]+)"/);
             if (match && match[1]) {
                 errorMessage = match[1];
             }
         } catch(e) {
             // If regex/parsing fails, just keep original
         }
      }

      setError(errorMessage);

      // If we get a rate limit error during background refresh, we might want to log it but not clear the UI
      if (isBackground) {
        console.warn("Background sync failed:", errorMessage);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handlePlayerClick = (playerName: string) => {
    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });

    // Update state to reflect the new search
    const newParams = { ...formData, filters: playerName };
    setFormData(newParams);

    // Trigger generation with new params immediately
    handleGenerate(false, newParams);
  };

  if (showLanding) {
    return (
        <LandingPage 
            onEnter={() => setShowLanding(false)} 
            hasActiveSession={recommendations.length > 0 || formData.filters !== ''}
        />
    );
  }

  // Determine header text
  const isDailyPicks = !formData.filters && recommendations.length > 0;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans selection:bg-emerald-500/30">
      {/* Header */}
      <header className="border-b border-gray-800 bg-gray-900/50 backdrop-blur sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => setShowLanding(true)}>
            <div className="bg-emerald-500/10 p-2 rounded border border-emerald-500/20">
              <BarChart3 className="text-emerald-500" size={24} />
            </div>
            <div>
              <h1 className="text-lg font-bold text-white tracking-tight">PRR <span className="text-gray-500 text-sm font-normal">| Parlay Recommendation Robot</span></h1>
              <div className="text-[10px] font-mono text-emerald-400 uppercase tracking-widest">v1.2.0 • STAT FILTERING ACTIVE</div>
            </div>
          </div>

          {/* Mobile Home Button */}
          <button 
             onClick={() => setShowLanding(true)}
             className="md:hidden p-2 text-gray-400 hover:text-white"
             title="Return Home"
          >
             <Home size={20} />
          </button>

          {/* Desktop Nav */}
          <div className="hidden md:flex items-center gap-6 text-sm text-gray-400">

             {/* Home Button (Desktop) */}
             <button 
                onClick={() => setShowLanding(true)}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg hover:bg-gray-800 hover:text-white transition-all group"
             >
                <Home size={16} className="text-gray-500 group-hover:text-emerald-400 transition-colors" />
                <span className="font-mono text-xs font-medium uppercase tracking-wider">Exit Terminal</span>
             </button>

             <div className="h-4 w-px bg-gray-800"></div>

             <span className="flex items-center gap-2 text-emerald-400 font-medium">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div> 
                Live Data Stream Active
             </span>
             <span className="font-mono">LATENCY: 42ms</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Intro / Dashboard */}
        <div className="mb-8">
          <InputForm 
            formData={formData} 
            setFormData={setFormData} 
            onSubmit={() => handleGenerate(false)} 
            isLoading={isLoading}
            lastSyncTime={lastSyncTime}
          />
        </div>

        {/* Results Area */}
        <div className="space-y-6">
          {error && (
            <div className="bg-rose-950/30 border border-rose-900 text-rose-200 p-4 rounded-lg flex items-center gap-3 animate-fadeIn">
              <ShieldAlert size={20} className="shrink-0" />
              <div className="overflow-hidden">
                <p className="font-bold">System Notification</p>
                <p className="text-sm opacity-80 truncate">{error}</p>
              </div>
            </div>
          )}

          {recommendations.length > 0 && (
             <div className="flex items-center justify-between mb-4 animate-fadeIn">
               <div>
                  <h3 className="text-xl font-bold text-white flex items-center gap-2">
                    {recommendations[0].type === 'player_profile' ? (
                       'Player Intelligence Report'
                    ) : isDailyPicks ? (
                       <><Zap className="text-yellow-400" fill="currentColor" size={20} /> TODAY'S TOP 3 VALUE PLAYS</>
                    ) : (
                       'Optimized Candidates'
                    )}
                  </h3>
                  {isDailyPicks && (
                    <p className="text-xs text-emerald-400 font-mono mt-1">
                      LIVE ALGORITHM PICKS • 3-LEG STRUCTURE • EXCLUSIVE
                    </p>
                  )}
               </div>
               <div className="flex items-center gap-4">
                 {isLoading && <span className="text-xs text-emerald-400 animate-pulse font-mono">SYNCING LIVE ODDS...</span>}
                 <span className="text-sm text-gray-500 font-mono hidden sm:block">Sorted by Utility Score (EV - Risk)</span>
               </div>
             </div>
          )}

          <div className="grid gap-6">
            {recommendations.map((item, index) => {
               if (item.type === 'player_profile') {
                   return <PlayerProfileCard key={item.id || index} data={item} />;
               }
               return (
                  <ParlayCard 
                    key={item.id || index} 
                    parlay={item} 
                    index={index} 
                    onPlayerClick={handlePlayerClick}
                  />
               );
            })}
          </div>

          {!isLoading && recommendations.length === 0 && !error && (
            <div className="text-center py-20 border border-dashed border-gray-800 rounded-xl">
              <div className="inline-block p-4 rounded-full bg-gray-900 mb-4">
                <BarChart3 className="text-gray-600" size={32} />
              </div>
              <h3 className="text-gray-400 font-medium text-lg">Initializing System...</h3>
              <p className="text-gray-600 max-w-md mx-auto mt-2">
                 Connecting to live odds providers and generating daily value picks.
              </p>
            </div>
          )}
        </div>
      </main>

      {/* Disclaimer Footer */}
      <footer className="border-t border-gray-900 mt-12 py-8 bg-gray-950">
        <div className="max-w-7xl mx-auto px-4 text-center">
            <p className="text-xs text-gray-600 max-w-2xl mx-auto leading-relaxed">
              DISCLAIMER: This system is for informational and entertainment purposes only. "PRR" uses simulated historical data and probability models which do not guarantee future results. Gambling involves risk. Please gamble responsibly. If you or someone you know has a gambling problem, call 1-800-GAMBLER.
            </p>
            <p className="text-[10px] text-gray-700 mt-4 font-mono">
              ENGINE: XGBoost v1.7.6 | DATA: SportRadar/Genius (Simulated) | LATENCY: 42ms
            </p>
        </div>
      </footer>

      {/* Only show full screen loader if we have no data to show yet. Background refreshes are silent/subtle. */}
      {isLoading && recommendations.length === 0 && <LoadingScreen />}
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { League, RiskLevel, UserInputState } from '../types';
import { BrainCircuit, DollarSign, RefreshCw, Zap, Database, Activity, Globe, Search, Clock, X, BarChart3, TrendingUp, ShieldAlert, Timer } from './Icons';

interface InputFormProps {
  formData: UserInputState;
  setFormData: React.Dispatch<React.SetStateAction<UserInputState>>;
  onSubmit: () => void;
  isLoading: boolean;
  lastSyncTime: Date | null;
}

export const InputForm: React.FC<InputFormProps> = ({ 
  formData, 
  setFormData, 
  onSubmit, 
  isLoading,
  lastSyncTime
}) => {
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('prr_search_history');
    if (saved) {
      try {
        setRecentSearches(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse search history", e);
      }
    }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    // Reset stat type if league changes to avoid invalid combinations
    if (name === 'league') {
        setFormData(prev => ({
          ...prev,
          league: value as League,
          statType: 'Any'
        }));
    } else {
        setFormData(prev => ({
          ...prev,
          [name]: name === 'bankroll' ? parseFloat(value) : value
        }));
    }

    if (name === 'filters') {
      setShowSuggestions(true);
    }
  };

  const saveToHistory = (term: string) => {
    if (!term || term.trim().length < 2) return;
    const cleanTerm = term.trim();
    // Remove duplicates and keep only last 5
    const newHistory = [cleanTerm, ...recentSearches.filter(s => s.toLowerCase() !== cleanTerm.toLowerCase())].slice(0, 5);
    setRecentSearches(newHistory);
    localStorage.setItem('prr_search_history', JSON.stringify(newHistory));
  };

  const clearHistory = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent closing dropdown immediately
    setRecentSearches([]);
    localStorage.removeItem('prr_search_history');
    setShowSuggestions(false);
  };

  const handleSubmission = () => {
    saveToHistory(formData.filters);
    setShowSuggestions(false);
    onSubmit();
  };

  const handleSuggestionClick = (term: string) => {
    setFormData(prev => ({ ...prev, filters: term }));
    setShowSuggestions(false);
  };

  const handleRiskSelection = (risk: RiskLevel) => {
    setFormData(prev => ({ ...prev, riskLevel: risk }));
  };

  // Helper to format time
  const formatTime = (date: Date | null) => {
    if (!date) return "CONNECTING...";
    return date.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  // Filter suggestions based on input
  const filteredSuggestions = recentSearches.filter(s => 
    s.toLowerCase().includes(formData.filters.toLowerCase())
  );

  const shouldShowDropdown = showSuggestions && (filteredSuggestions.length > 0 || (formData.filters === '' && recentSearches.length > 0));

  // Determine available stat options based on selected League
  const statOptions = useMemo(() => {
    switch(formData.league) {
        case League.NBA: return ['Any', 'Points', 'Rebounds', 'Assists', 'Threes', 'PRA', 'Steals/Blocks'];
        case League.NFL: return ['Any', 'Passing Yds', 'Rushing Yds', 'Receiving Yds', 'Touchdowns'];
        case League.MLB: return ['Any', 'Strikeouts', 'Total Bases', 'Hits', 'Home Runs'];
        default: return ['Any'];
    }
  }, [formData.league]);

  // Visual configuration for the Risk Gauge
  const riskConfig = [
    { level: RiskLevel.VERY_LOW, color: 'bg-emerald-500', label: 'Safe', icon: <ShieldAlert size={12} /> },
    { level: RiskLevel.LOW, color: 'bg-teal-500', label: 'Low', icon: <Activity size={12} /> },
    { level: RiskLevel.MEDIUM, color: 'bg-yellow-500', label: 'Med', icon: <TrendingUp size={12} /> },
    { level: RiskLevel.HIGH, color: 'bg-orange-500', label: 'High', icon: <Zap size={12} /> },
    { level: RiskLevel.VERY_HIGH, color: 'bg-rose-600', label: 'Max', icon: <BrainCircuit size={12} /> }
  ];

  return (
    <div className="bg-gray-850 p-6 rounded-xl border border-gray-800 shadow-lg relative z-30">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div className="flex items-center gap-2">
          <BrainCircuit className="text-emerald-400" size={24} />
          <h2 className="text-xl font-bold text-white">Model Configuration</h2>
        </div>

        <div className="flex items-center gap-3">
          {/* Refresh Data Button */}
          <button 
            onClick={handleSubmission}
            disabled={isLoading}
            className="flex items-center justify-center p-2 bg-gray-900 border border-gray-800 rounded-lg hover:bg-gray-800 hover:border-gray-700 transition-all text-gray-400 hover:text-white disabled:opacity-50 disabled:cursor-not-allowed group"
            title="Force Refresh Data"
          >
            <RefreshCw size={18} className={`group-hover:text-emerald-400 transition-colors ${isLoading ? 'animate-spin text-emerald-500' : ''}`} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

        {/* Search Bar */}
        <div className="md:col-span-4 relative" ref={searchContainerRef}>
          <label className="block text-xs text-emerald-400 uppercase tracking-wider mb-2 font-bold flex items-center gap-2">
             <Search size={12} /> Search Player / Team
          </label>
          <div className="relative group">
            <input 
              type="text" 
              name="filters"
              value={formData.filters}
              onChange={handleChange}
              onFocus={() => setShowSuggestions(true)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSubmission();
              }}
              autoComplete="off"
              placeholder="e.g. 'LeBron' or 'Lakers'"
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 pl-10 focus:outline-none focus:border-emerald-500 transition-colors group-hover:border-gray-600 text-sm"
            />
            <Search size={16} className="absolute left-3 top-3.5 text-gray-500 group-hover:text-emerald-400 transition-colors" />
            <div className="absolute right-3 top-3.5">
                <span className="text-[10px] bg-gray-800 text-gray-400 px-1.5 py-0.5 rounded border border-gray-700">LIVE LOOKUP</span>
            </div>
          </div>

          {/* Search History Dropdown */}
          {shouldShowDropdown && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-700 rounded-lg shadow-xl overflow-hidden z-50">
              <div className="py-1">
                <div className="px-3 py-2 text-[10px] uppercase text-gray-500 font-bold tracking-wider border-b border-gray-800 flex justify-between items-center">
                  <span>Recent Searches</span>
                  <button onClick={clearHistory} className="text-gray-600 hover:text-rose-400 transition-colors flex items-center gap-1">
                    <X size={10} /> Clear
                  </button>
                </div>
                {filteredSuggestions.map((term, idx) => (
                  <div 
                    key={idx}
                    onClick={() => handleSuggestionClick(term)}
                    className="px-3 py-2.5 hover:bg-gray-800 cursor-pointer flex items-center gap-3 transition-colors text-sm text-gray-300"
                  >
                    <Clock size={14} className="text-gray-500" />
                    {term}
                  </div>
                ))}
                {filteredSuggestions.length === 0 && (
                   <div className="px-3 py-4 text-center text-xs text-gray-600 italic">
                     No matching history
                   </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* League Selector */}
        <div className="md:col-span-2">
          <label className="block text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium">League</label>
          <div className="relative">
            <select 
              name="league"
              value={formData.league}
              onChange={handleChange}
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 appearance-none focus:outline-none focus:border-emerald-500 transition-colors text-sm"
            >
              {Object.values(League).map((l) => (
                <option key={l} value={l}>{l}</option>
              ))}
            </select>
            <div className="absolute right-3 top-3.5 pointer-events-none text-gray-500">
               <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
            </div>
          </div>
        </div>

        {/* Stat Focus Selector */}
        <div className="md:col-span-2">
          <label className="block text-xs text-emerald-400 uppercase tracking-wider mb-2 font-bold flex items-center gap-1">
             <BarChart3 size={12} /> Stat Focus
          </label>
          <div className="relative">
             <select 
              name="statType"
              value={formData.statType}
              onChange={handleChange}
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 appearance-none focus:outline-none focus:border-emerald-500 transition-colors text-sm"
            >
              {statOptions.map((opt) => (
                <option key={opt} value={opt}>{opt}</option>
              ))}
            </select>
            <div className="absolute right-3 top-3.5 pointer-events-none text-gray-500">
               <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
            </div>
          </div>
        </div>

        {/* Custom Visual Risk Gauge */}
        <div className="md:col-span-4">
          <label className="block text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium flex justify-between">
            <span>Risk Tolerance</span>
            <span className="text-white font-mono text-[10px]">{formData.riskLevel}</span>
          </label>
          <div className="flex items-center gap-1 bg-gray-900 p-1 rounded-lg border border-gray-700 h-[46px]">
            {riskConfig.map((config, index) => {
              const isSelected = formData.riskLevel === config.level;
              return (
                <button
                  key={config.level}
                  onClick={() => handleRiskSelection(config.level)}
                  className={`
                    flex-1 h-full rounded transition-all duration-300 flex items-center justify-center gap-1 group relative
                    ${isSelected ? `${config.color} text-gray-900 shadow-lg` : 'hover:bg-gray-800 text-gray-500 hover:text-gray-300'}
                  `}
                  title={config.level}
                >
                  <span className={`${isSelected ? 'scale-110' : 'scale-100'} transition-transform`}>
                    {config.icon}
                  </span>
                  {/* Tooltip on hover if not selected */}
                  {!isSelected && (
                     <div className="hidden group-hover:block absolute bottom-full mb-2 left-1/2 -translate-x-1/2 text-[10px] bg-gray-950 text-white px-2 py-1 rounded border border-gray-800 whitespace-nowrap z-20">
                        {config.level}
                     </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Row 2: Bankroll & Action */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mt-6 items-end">
         <div>
            <label className="block text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium">Bankroll Allocation ($)</label>
            <div className="relative">
                <input 
                type="number" 
                name="bankroll"
                value={formData.bankroll}
                onChange={handleChange}
                className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 pl-10 focus:outline-none focus:border-emerald-500 transition-colors font-mono text-sm"
                />
                <DollarSign size={16} className="absolute left-3 top-3.5 text-gray-500" />
            </div>
         </div>

         <div className="flex justify-end">
            <button 
            onClick={handleSubmission} 
            disabled={isLoading}
            className={`
                w-full sm:w-auto flex items-center justify-center gap-2 px-8 py-3 rounded-lg font-bold tracking-wide transition-all
                ${isLoading 
                ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-500/20 hover:shadow-emerald-500/40 active:transform active:scale-95'
                }
            `}
            >
            {isLoading ? (
                <>
                <RefreshCw className="animate-spin" size={18} />
                SCANNING BOOKS...
                </>
            ) : (
                <>
                <BrainCircuit size={18} />
                RUN SIMULATION
                </>
            )}
            </button>
         </div>
      </div>

      {/* Live Data Sources Indicator */}
      <div className="mt-4 p-3 bg-gray-900/50 rounded-lg border border-gray-800 flex flex-wrap gap-4 items-center justify-between animate-fadeIn">
          <div className="flex flex-wrap gap-4 items-center">
            <span className="text-[10px] uppercase text-gray-500 font-bold tracking-widest flex items-center gap-1">
                <Globe size={10} /> Live Grounding:
            </span>
            <div className="flex items-center gap-2">
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                <span className="text-xs text-gray-300 font-medium">Live Web Search (Google Grounding)</span>
            </div>
            <div className="flex items-center gap-2">
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse delay-75"></div>
                <span className="text-xs text-gray-300 font-medium">DK / FD / PrizePicks / Underdog</span>
            </div>
          </div>

          <div className="flex items-center gap-2 pl-4 border-l border-gray-800 hidden sm:flex">
             <Timer size={12} className="text-gray-500" />
             <span className="text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                SYNCED: <span className="text-emerald-400 font-bold">{formatTime(lastSyncTime)}</span>
             </span>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { League, RiskLevel, UserInputState } from '../types';
import { BrainCircuit, DollarSign, RefreshCw, Zap, Database, Activity, Globe, Search, Clock, X, BarChart3, TrendingUp, ShieldAlert, Timer,  Calendar } from './Icons';

interface InputFormProps {
  formData: UserInputState;
  setFormData: React.Dispatch<React.SetStateAction<UserInputState>>;
  onSubmit: () => void;
  isLoading: boolean;
  lastSyncTime: Date | null;
}

export const InputForm: React.FC<InputFormProps> = ({ 
  formData, 
  setFormData, 
  onSubmit, 
  isLoading,
  lastSyncTime
}) => {
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('prr_search_history');
    if (saved) {
      try {
        setRecentSearches(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse search history", e);
      }
    }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    // Reset stat type if league changes to avoid invalid combinations
    if (name === 'league') {
        setFormData(prev => ({
          ...prev,
          league: value as League,
          statType: 'Any'
        }));
    } else {
        setFormData(prev => ({
          ...prev,
          [name]: name === 'bankroll' ? parseFloat(value) : value
        }));
    }

    if (name === 'filters') {
      setShowSuggestions(true);
    }
  };

  const saveToHistory = (term: string) => {
    if (!term || term.trim().length < 2) return;
    const cleanTerm = term.trim();
    // Remove duplicates and keep only last 5
    const newHistory = [cleanTerm, ...recentSearches.filter(s => s.toLowerCase() !== cleanTerm.toLowerCase())].slice(0, 5);
    setRecentSearches(newHistory);
    localStorage.setItem('prr_search_history', JSON.stringify(newHistory));
  };

  const clearHistory = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent closing dropdown immediately
    setRecentSearches([]);
    localStorage.removeItem('prr_search_history');
    setShowSuggestions(false);
  };

  const handleSubmission = () => {
    saveToHistory(formData.filters);
    setShowSuggestions(false);
    onSubmit();
  };

  const handleSuggestionClick = (term: string) => {
    setFormData(prev => ({ ...prev, filters: term }));
    setShowSuggestions(false);
  };

  const handleRiskSelection = (risk: RiskLevel) => {
    setFormData(prev => ({ ...prev, riskLevel: risk }));
  };

  // Helper to format time
  const formatTime = (date: Date | null) => {
    if (!date) return "CONNECTING...";
    return date.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  // Filter suggestions based on input
  const filteredSuggestions = recentSearches.filter(s => 
    s.toLowerCase().includes(formData.filters.toLowerCase())
  );

  const shouldShowDropdown = showSuggestions && (filteredSuggestions.length > 0 || (formData.filters === '' && recentSearches.length > 0));

  // Determine available stat options based on selected League
  const statOptions = useMemo(() => {
    switch(formData.league) {
        case League.NBA: return ['Any', 'Points', 'Rebounds', 'Assists', 'Threes', 'PRA', 'Steals/Blocks'];
        case League.NFL: return ['Any', 'Passing Yds', 'Rushing Yds', 'Receiving Yds', 'Touchdowns'];
        case League.MLB: return ['Any', 'Strikeouts', 'Total Bases', 'Hits', 'Home Runs'];
        default: return ['Any'];
    }
  }, [formData.league]);

  // Visual configuration for the Risk Gauge
  const riskConfig = [
    { level: RiskLevel.VERY_LOW, color: 'bg-emerald-500', label: 'Safe', icon: <ShieldAlert size={12} /> },
    { level: RiskLevel.LOW, color: 'bg-teal-500', label: 'Low', icon: <Activity size={12} /> },
    { level: RiskLevel.MEDIUM, color: 'bg-yellow-500', label: 'Med', icon: <TrendingUp size={12} /> },
    { level: RiskLevel.HIGH, color: 'bg-orange-500', label: 'High', icon: <Zap size={12} /> },
    { level: RiskLevel.VERY_HIGH, color: 'bg-rose-600', label: 'Max', icon: <BrainCircuit size={12} /> }
  ];

  return (
    <div className="bg-gray-850 p-6 rounded-xl border border-gray-800 shadow-lg relative z-30">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div className="flex items-center gap-2">
          <BrainCircuit className="text-emerald-400" size={24} />
          <h2 className="text-xl font-bold text-white">Model Configuration</h2>
        </div>

        <div className="flex items-center gap-3">
          {/* Refresh Data Button */}
          <button 
            onClick={handleSubmission}
            disabled={isLoading}
            className="flex items-center justify-center p-2 bg-gray-900 border border-gray-800 rounded-lg hover:bg-gray-800 hover:border-gray-700 transition-all text-gray-400 hover:text-white disabled:opacity-50 disabled:cursor-not-allowed group"
            title="Force Refresh Data"
          >
            <RefreshCw size={18} className={`group-hover:text-emerald-400 transition-colors ${isLoading ? 'animate-spin text-emerald-500' : ''}`} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

        {/* Search Bar */}
        <div className="md:col-span-4 relative" ref={searchContainerRef}>
          <label className="block text-xs text-emerald-400 uppercase tracking-wider mb-2 font-bold flex items-center gap-2">
             <Search size={12} /> Search Context
          </label>
          <div className="relative group">
            <input 
              type="text" 
              name="filters"
              value={formData.filters}
              onChange={handleChange}
              onFocus={() => setShowSuggestions(true)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSubmission();
              }}
              autoComplete="off"
              placeholder="Player, Team, Game (LAL vs BOS), or Date..."
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 pl-10 focus:outline-none focus:border-emerald-500 transition-colors group-hover:border-gray-600 text-sm"
            />
            <Search size={16} className="absolute left-3 top-3.5 text-gray-500 group-hover:text-emerald-400 transition-colors" />

            {/* Context Badge */}
            <div className="absolute right-3 top-3.5">
               {formData.filters ? (
                 <span className="text-[10px] bg-emerald-500/20 text-emerald-400 px-1.5 py-0.5 rounded border border-emerald-500/30 flex items-center gap-1">
                    <Database size={8} /> CONTEXT
                 </span>
               ) : (
                 <span className="text-[10px] bg-gray-800 text-gray-400 px-1.5 py-0.5 rounded border border-gray-700">OMNI-SEARCH</span>
               )}
            </div>
          </div>

          {/* Tips for format */}
          {showSuggestions && !recentSearches.length && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-700 rounded-lg shadow-xl z-50 p-3">
                 <p className="text-[10px] text-gray-500 uppercase font-bold mb-2">Supported Formats</p>
                 <div className="space-y-2">
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Search size={12} className="text-blue-500" /> "LeBron James" <span className="text-gray-600">(Player Profile)</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Globe size={12} className="text-purple-500" /> "Lakers vs Warriors" <span className="text-gray-600">(Game Value)</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Calendar size={12} className="text-emerald-500" /> "NBA games Sunday" <span className="text-gray-600">(Time Filter)</span>
                    </div>
                 </div>
              </div>
          )}

          {/* Search History Dropdown */}
          {shouldShowDropdown && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-700 rounded-lg shadow-xl overflow-hidden z-50">
              <div className="py-1">
                <div className="px-3 py-2 text-[10px] uppercase text-gray-500 font-bold tracking-wider border-b border-gray-800 flex justify-between items-center">
                  <span>Recent Searches</span>
                  <button onClick={clearHistory} className="text-gray-600 hover:text-rose-400 transition-colors flex items-center gap-1">
                    <X size={10} /> Clear
                  </button>
                </div>
                {filteredSuggestions.map((term, idx) => (
                  <div 
                    key={idx}
                    onClick={() => handleSuggestionClick(term)}
                    className="px-3 py-2.5 hover:bg-gray-800 cursor-pointer flex items-center gap-3 transition-colors text-sm text-gray-300"
                  >
                    <Clock size={14} className="text-gray-500" />
                    {term}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* League Selector */}
        <div className="md:col-span-2">
          <label className="block text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium">League</label>
          <div className="relative">
            <select 
              name="league"
              value={formData.league}
              onChange={handleChange}
              className="w-full bg-gray-900 border border-gray-700 text-white rounded-lg p-3 appearance-none focus:outline-none focus:border-emerald-500 transition-colors text-sm"
            >
              {Object.values(League).map((l) => (
                <option key={l} value={l}>{l}</option>
              ))}
