// --- Main Service Logic ---

const cleanJsonText = (text: string): string => {
    let cleaned = text.replace(/```json/g, '').replace(/```/g, '');
    const startIndex = cleaned.indexOf('{');
    const endIndex = cleaned.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        throw new Error("AI returned unstructured text.");
    }

    cleaned = cleaned.substring(startIndex, endIndex + 1);
    // Fix common JSON errors: remove '+' from numbers
    cleaned = cleaned.replace(/:\s*\+(\d+)/g, ': $1');
    return cleaned;
};

const parseResponse = (text: string): ParlayRecommendation[] => {
    try {
        const jsonString = cleanJsonText(text);
        const parsed = JSON.parse(jsonString);

        return (parsed.recommendations || []).map((rec: any, index: number) => ({
            type: rec.type || 'parlay', // Default to parlay if undefined, Prompt controls actual value
            id: rec.id || `rec-${index}-${Date.now()}`,
            summary: rec.summary || "Analysis generated.",
            totalOdds: Number(rec.totalOdds) || 0,
            jointProbAdjusted: Number(rec.jointProbAdjusted) || 0,
            expectedValue: Number(rec.expectedValue) || 0,
            kellyStake: Number(rec.kellyStake) || 0,
            correlationScore: Number(rec.correlationScore) || 0,
            varianceScore: Number(rec.varianceScore) || 0,
            timestamp: rec.timestamp || new Date().toISOString(),
            legs: (rec.legs || []).map((leg: any) => ({
                playerId: leg.playerId || "unknown",
                playerName: leg.playerName || "Unknown Player",
                team: leg.team || "N/A",
                opponent: leg.opponent || "N/A",
                statType: leg.statType || "Prop",
                line: Number(leg.line) || 0,
                prediction: leg.prediction || "Over",
                bookOdds: Number(leg.bookOdds) || -110,
                modelProb: Number(leg.modelProb) || 0.60,
                impliedProb: Number(leg.impliedProb) || 0.55,
                edge: Number(leg.edge) || 0,
                rationale: leg.rationale || "Analysis provided."
            }))
        }));
    } catch (e) {
        console.warn("JSON Parse Failed, falling back to mock. Raw Text:", text);
        throw e; 
    }
};

export const generateParlays = async (
  league: League,
  risk: RiskLevel,
  filters: string,
  statType: string = 'Any'
): Promise<ParlayRecommendation[]> => {
    const apiKey = process.env.API_KEY;
    const hasSearchTerm = filters && filters.length > 2;

    if (!apiKey) {
        console.warn("No API Key. Returning mocks.");
        return hasSearchTerm ? [getMockPlayerProfile(filters)] : getMockParlays(league, statType);
    }

    try {
        const ai = new GoogleGenAI({ apiKey });
        const modelId = "gemini-2.5-flash";

        // Enhanced prompt for Omni-Search with MANDATORY Live Verification
        const prompt = `
          Act as a Senior Quantitative Sports Analyst and Betting Model.

          TASK:
          Generate JSON betting recommendations for:
          - League: ${league}
          - Search Context: ${hasSearchTerm ? `"${filters}"` : "None (Generate Daily Top 3)"}
          - Risk Profile: ${risk}
          - Stat Filter: ${statType}

          MANDATORY LIVE DATA VERIFICATION (Use Google Search):
          Before selecting ANY player, you MUST use the 'googleSearch' tool to verify:
          1. INJURY STATUS: Search "[Player Name] injury status ESPN". Do NOT recommend players who are OUT, DOUBTFUL, or INJURED.
          2. ROSTER CHECK: Search "[Player Name] current team". Ensure they are on the correct roster and not traded.
          3. NEWS: Check for recent news (e.g., "minutes restriction", "starting lineup change") from sources like ESPN, RotoWire, or CBS Sports.

          MANDATORY LINE SHOPPING & BOOK SCAN:
          You MUST search for and compare lines from these 5 specific platforms:
          1. DraftKings
          2. FanDuel
          3. PrizePicks
          4. Underdog Fantasy
          5. Chalkboard

          INSTRUCTION: Find the most favorable line for the user. 
          - Example: If DraftKings is 24.5 and PrizePicks is 23.5 for an Over, use the 23.5 line.
          - If a line is specific to a DFS site (like "Demons" on PrizePicks), mention it in the rationale.

          SEARCH LOGIC:
          1. IF the Search Context names a SPECIFIC ATHLETE (e.g., "LeBron James"):
             - Verify they are healthy and active.
             - Return exactly 1 object with type "player_profile".
             - Include 5 distinct bet legs for that athlete.

          2. IF the Search Context names a TEAM (e.g. "Lakers"), MATCHUP (e.g. "KC vs BUF"), or TIME:
             - Return exactly 3 distinct "parlay" objects.
             - FILTER the legs to ONLY include players relevant to that context.
             - Example: If "Lakers", only include Lakers players in the parlays.

          3. IF Search Context is Empty:
             - Return exactly 3 distinct "parlay" objects (Daily Top 3).
             - Select healthy, active stars.

          DATA SOURCES & MATH INSTRUCTIONS:
          1. Use verified live data from sports agencies (ESPN, RotoWire) via Google Search.
          2. CALCULATE 'modelProb' (0.00-1.00) based on:
             - Hit Rate in Last 10 Games.
             - Adjust for Matchup Difficulty (Opponent Rank).
             - Adjust for Venue and recent Injury News (e.g. star teammate out).
          3. CALCULATE 'impliedProb' from 'bookOdds'.
          4. CALCULATE 'edge' = (modelProb - impliedProb) * 100.

          RESPONSE REQUIREMENTS:
          - 'rationale': MUST be dense and technical. Max 20 words.
             * REQUIRED: Mention "Hit Rate" (e.g. 8/10 L10).
             * REQUIRED: Mention Matchup Rank (e.g. vs 28th Def).
             * REQUIRED: Mention Line Value (e.g. "PrizePicks line 1.5 lower than DK").
          - 'prediction': strictly "Over" or "Under".
          - 'line': Use standard market lines (e.g. 24.5).

          OUTPUT FORMAT (JSON ONLY, NO MARKDOWN):
          {
            "recommendations": [
              {
                "type": "parlay" OR "player_profile",
                "summary": "Detailed technical summary of the edge found.",
                "totalOdds": number (integer, e.g. 450 for +450),
                "jointProbAdjusted": number (float 0-1),
                "expectedValue": number (float %),
                "kellyStake": number (float %),
                "correlationScore": number (float 0-1),
                "varianceScore": number (1-10),
                "legs": [
                  {
                    "playerName": "string",
                    "team": "string (ABBR)",
                    "opponent": "string (ABBR)",
                    "statType": "string",
                    "line": number,
                    "prediction": "Over" | "Under",
                    "bookOdds": number (e.g. -115),
                    "modelProb": number (e.g. 0.62),
                    "impliedProb": number (e.g. 0.53),
                    "edge": number (e.g. 9.5),
                    "rationale": "string (See requirements)"
                  }
                ]
              }
            ]
          }
        `;

        const response = await ai.models.generateContent({
            model: modelId,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
                temperature: 0.4, 
            }
        });

        if (!response.text) throw new Error("No text returned from model");
        return parseResponse(response.text);

    } catch (error: any) {
        console.warn("Gemini API Unavailable or Parse Failed. Switching to Simulation.", error.message);
        // Fallback Logic: If search term looks like a person (heuristic), return profile, else parlays
        // This is a simple mock heuristic. In a real app, you'd check a DB.
        if (hasSearchTerm && !filters.includes(" vs ") && !filters.includes("Game") && filters.split(' ').length <= 3) {
            return [getMockPlayerProfile(filters)];
        } else {
            return getMockParlays(league, statType, filters);
        }
    }
};

