                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                <span className="text-xs text-gray-300 font-medium">ESPN / RotoWire / Official Team Sites</span>
            </div>
            <div className="flex items-center gap-2">
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse delay-75"></div>
                <span className="text-xs text-gray-300 font-medium">Odds: DK / FD / PrizePicks / Underdog / Chalkboard</span>
            </div>
