            {/* Context Badge */}
            <div className="absolute right-3 top-3.5">
               {formData.filters ? (
                 <span className="text-[10px] bg-emerald-500/20 text-emerald-400 px-1.5 py-0.5 rounded border border-emerald-500/30 flex items-center gap-1">
                    <Database size={8} /> CONTEXT
                 </span>
               ) : (
                 <span className="text-[10px] bg-gray-800 text-gray-400 px-1.5 py-0.5 rounded border border-gray-700">OMNI-SEARCH</span>
               )}
            </div>
          </div>

          {/* Tips for format */}
          {showSuggestions && !recentSearches.length && !formData.filters && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-700 rounded-lg shadow-xl z-50 p-3">
                 <p className="text-[10px] text-gray-500 uppercase font-bold mb-2">Supported Formats</p>
                 <div className="space-y-2">
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Search size={12} className="text-blue-500" /> "LeBron James" <span className="text-gray-600">(Player Profile)</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Globe size={12} className="text-purple-500" /> "Lakers vs Warriors" <span className="text-gray-600">(Game Value)</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Calendar size={12} className="text-emerald-500" /> "NBA games Sunday" <span className="text-gray-600">(Time Filter)</span>
                    </div>
                 </div>
              </div>
          )}

          {/* Combined Autocomplete Dropdown */}
          {shouldShowDropdown && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-700 rounded-lg shadow-xl overflow-hidden z-50 animate-fadeIn">
              <div className="py-1 max-h-64 overflow-y-auto custom-scrollbar">

                {/* Live Suggestions Section */}
                {liveSuggestions.length > 0 && (
                    <div className="mb-1">
                        <div className="px-3 py-1.5 text-[10px] uppercase text-emerald-500 font-bold tracking-wider bg-emerald-950/20 flex items-center gap-2">
                             <Zap size={10} fill="currentColor" /> Live Market Data
                        </div>
                        {liveSuggestions.map((item, idx) => (
                            <div 
                                key={`live-${idx}`}
                                onClick={() => handleSuggestionClick(item.label)}
                                className="px-3 py-2.5 hover:bg-gray-800 cursor-pointer flex items-center justify-between transition-colors text-sm text-gray-200 border-b border-gray-800/50 last:border-0"
                            >
                                <div className="flex items-center gap-3">
                                    {item.type === 'player' ? <User size={14} className="text-gray-400" /> : <Trophy size={14} className="text-yellow-500" />}
                                    <div className="flex flex-col">
                                        <span className="font-semibold">{item.label}</span>
                                        <span className="text-[10px] text-gray-500">{item.sub}</span>
                                    </div>
                                </div>
                                <div className="text-[10px] bg-gray-800 text-gray-400 px-1 rounded border border-gray-700">
                                    {item.league}
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {/* History Section */}
                {historySuggestions.length > 0 && (
                    <div>
                        <div className="px-3 py-2 text-[10px] uppercase text-gray-500 font-bold tracking-wider border-b border-gray-800 flex justify-between items-center bg-gray-900/80">
                            <span>Recent History</span>
                            <button onClick={clearHistory} className="text-gray-600 hover:text-rose-400 transition-colors flex items-center gap-1">
                                <X size={10} /> Clear
                            </button>
                        </div>
                        {historySuggestions.map((term, idx) => (
                            <div 
                                key={`hist-${idx}`}
                                onClick={() => handleSuggestionClick(term)}
                                className="px-3 py-2.5 hover:bg-gray-800 cursor-pointer flex items-center gap-3 transition-colors text-sm text-gray-300"
                            >
